package com.farika.soundflow;
import android.app.job.*;import android.os.*;import org.json.*;import java.util.concurrent.*;
/** Quiet periodic checks and resumable transfers. Only a transfer creates a notification. */
public class AutoDownloadJob extends JobService {
 private final ConcurrentHashMap<Integer,FutureTask<Void>> jobs=new ConcurrentHashMap<>();private final ConcurrentHashMap<Integer,DownloadNotice> notices=new ConcurrentHashMap<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 @Override public boolean onStartJob(JobParameters p){if(!AutoDownloads.connected(this)||Session.get(this).isEmpty())return false;String user=DownloadSync.owner(this);long cancellation=DownloadCancellation.ticket();FutureTask<Void> task=new FutureTask<>(()->{long deadline=System.currentTimeMillis()+8*60*1000;try(SyncDb db=new SyncDb(this)){for(JSONObject plan:db.workPlans(user)){if(Thread.currentThread().isInterrupted()||!DownloadCancellation.current(cancellation))break;String id=plan.optString("id");SyncRequests.Request request=SyncRequests.get(this,user,id);if(!CheckCadence.runnable(this,db,user,plan,System.currentTimeMillis()))continue;if(!(request.manual?AutoDownloads.connected(this):AutoDownloads.allowed(this))){db.status(user,id,AutoDownloads.waitReason(this));continue;}boolean refresh=CheckCadence.refresh(this,user,plan,request,System.currentTimeMillis());long ticket=AutoDownloadGate.ticket(user,id);DownloadNotice notice=new DownloadNotice(this,plan.optString("title"));notices.put(p.getJobId(),notice);
    try{DownloadSync.run(this,user,id,plan.optString("title"),plan.optString("kind"),refresh,request.force,new DownloadSync.Monitor(){public boolean cancelled(){return !AutoDownloadGate.current(user,id,ticket)||!DownloadCancellation.current(cancellation)||!(request.manual?AutoDownloads.connected(AutoDownloadJob.this):AutoDownloads.allowed(AutoDownloadJob.this))||Thread.currentThread().isInterrupted()||System.currentTimeMillis()>deadline;}public void progress(String text,int percent){notice.progress(text,percent);}public void transfer(String text,int percent){notice.transfer(text,percent);}public void finished(){notice.close();}});}catch(Exception e){if(e instanceof ScApi.ApiError&&((ScApi.ApiError)e).status==401)break;}finally{notice.close();notices.remove(p.getJobId(),notice);SyncRequests.consume(this,user,id,request);if(SyncRequests.pending(this,user,id))db.active(user,id,true);}
   }}finally{jobs.remove(p.getJobId());main.post(()->{jobFinished(p,false);AutoDownloads.schedule(this);AutoDownloads.retry(this);});}return null;});jobs.put(p.getJobId(),task);worker.execute(task);return true;}
 @Override public boolean onStopJob(JobParameters p){DownloadNotice n=notices.remove(p.getJobId());if(n!=null)n.close();FutureTask<Void> f=jobs.remove(p.getJobId());if(f!=null)f.cancel(true);AutoDownloads.retry(this);return true;}
 @Override public void onDestroy(){for(DownloadNotice n:notices.values())n.close();notices.clear();for(FutureTask<Void> f:jobs.values())f.cancel(true);worker.shutdownNow();main.removeCallbacksAndMessages(null);AutoDownloads.retry(this);super.onDestroy();}
}
